"""import { hasRoleAtLeast } from "@/types/member";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/** Staff and admins see private projects without being members. */
function seesAllPrivateProjects(actor: Actor): boolean {
  return actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin");
}

/**
 * Whether `actor` may see `project`. Only `private` projects are restricted:
 * staff, admins and owners, the project lead and explicit members see them.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (seesAllPrivateProjects(actor)) return true;
  if (project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * Throws `NotFoundError` rather than a permission error, so a hidden project
 * is indistinguishable from one that does not exist.
 */
export async function assertProjectVisible(
  actor: Actor,
  project: Project,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError("Project", project.id);
  }
}

/** Loads a project by id and enforces visibility; for callers starting from a child row. */
export async function requireVisibleProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  await assertProjectVisible(actor, project);
  return project;
}

/**
 * Ids of private projects the actor may not see, to be excluded from listings.
 * Empty for staff and admins, who see everything.
 */
export async function hiddenPrivateProjectIds(
  actor: Actor,
): Promise<readonly ProjectId[]> {
  if (seesAllPrivateProjects(actor)) return [];

  const memberOf = new Set(
    await projectMemberRepo.listProjectIdsForUser(actor.orgId, actor.userId),
  );
  const privateProjects = await projectRepo.listPrivateProjects(actor.orgId);

  return privateProjects
    .filter(
      (project) =>
        project.leadId !== actor.userId && !memberOf.has(project.id),
    )
    .map((project) => project.id);
}
